def maxSumThreeWindows(nums, k):
    n = len(nums)
    m = n - k + 1                     # number of window starts
    w = [0] * m
    s = sum(nums[:k])
    w[0] = s
    for i in range(1, m):
        s += nums[i + k - 1] - nums[i - 1]
        w[i] = s
    left = w[:]
    for i in range(1, m):
        if left[i - 1] > left[i]:
            left[i] = left[i - 1]
    right = w[:]
    for i in range(m - 2, -1, -1):
        if right[i + 1] > right[i]:
            right[i] = right[i + 1]
    best = 0
    for b in range(k, m - k):
        total = left[b - k] + w[b] + right[b + k]
        if total > best:
            best = total
    return best
